	/** Records the character encoding in effect when a parameter is first read. */
	private static final class EncodingTrackingRequest extends jakarta.servlet.http.HttpServletRequestWrapper {
		private boolean parameterRead;
		private String encodingAtFirstParameterRead;

		private EncodingTrackingRequest(HttpServletRequest request) {
			super(request);
		}

		private void recordRead() {
			if (!parameterRead) {
				parameterRead = true;
				encodingAtFirstParameterRead = getCharacterEncoding();
			}
		}

		@Override
		public String getParameter(String name) {
			recordRead();
			return super.getParameter(name);
		}

		@Override
		public String[] getParameterValues(String name) {
			recordRead();
			return super.getParameterValues(name);
		}

		@Override
		public Map<String, String[]> getParameterMap() {
			recordRead();
			return super.getParameterMap();
		}

		@Override
		public java.util.Enumeration<String> getParameterNames() {
			recordRead();
			return super.getParameterNames();
		}
	}

